function Todo() {
  const [items, setItems] = useState([]);
  const add = (text) => setItems((prev) => [...prev, { id: crypto.randomUUID(), text }]);
  return <ul>{items.map((it) => <li key={it.id}>{it.text}</li>)}</ul>;
}

